  bank=gl.createAccount(maker,new AccountCommand("BANK","Synthetic bank","ASSET","DEBIT","POSTING","BANK",null));capital=gl.createAccount(maker,new AccountCommand("CAPITAL","Synthetic capital","EQUITY","CREDIT","POSTING","CAPITAL",null));policy=UUID.randomUUID();var decisions=new EnumMap<PolicyDecision,String>(PolicyDecision.class);for(var key:PolicyDecision.values())decisions.put(key,"Synthetic reviewed evidence only");var matrix=new EnumMap<PostingEvent,PostingRule>(PostingEvent.class);for(var key:PostingEvent.values())matrix.put(key,new PostingRule(PostingPermission.ALLOWED,"Synthetic treatment"));var mappings=Map.of("DISBURSEMENT_CLEARING",bank,"REPAYMENT_CLEARING",bank,"OWNER_CAPITAL",capital);var mapper=JsonMapper.builder().findAndAddModules().build();jdbc.update("INSERT INTO accounting_policies(id,sacco_id,policy_version,effective_from,opening_date,authoritative_ledger,decisions_json,posting_matrix_json,account_mappings_json,evidence_reference,maker_id,request_key,created_at) VALUES(?,?,1,?,?,'LOCAL_GL',?,?,?,'Synthetic evidence',?,?,?)",policy,institution,DAY,DAY,mapper.writeValueAsString(decisions),mapper.writeValueAsString(matrix),mapper.writeValueAsString(mappings),maker.getMemberId(),UUID.randomUUID(),now);jdbc.update("INSERT INTO accounting_policy_approvals(policy_id,sacco_id,policy_version,effective_from,checker_id,decision,evidence_reference,reason,decided_at) VALUES(?,?,1,?,?,'APPROVED','Synthetic independent policy evidence','Test only',?)",policy,institution,DAY,checker.getMemberId(),now);when(policies.requireApprovedLocalPolicy(eq(institution),any())).thenReturn(new PolicySnapshot(policy,institution,1,DAY,DAY,AuthoritativeLedger.LOCAL_GL,decisions,matrix,mappings,"Synthetic evidence",maker.getMemberId(),AccountingPolicyService.Decision.APPROVED,checker.getMemberId(),"Synthetic independent review","Test only",now));
