  UUID certificate=closing.certify(maker,bank,DAY,"OPENING",new BigDecimal("1000.01"),"Synthetic verified bank opening source");closing.reviewCertificate(checker,certificate,"Independent opening reconciliation review");UUID close=closing.proposeClose(maker,period,"Synthetic opening-only close",false);closing.approveClose(checker,close,"Independent close evidence");if(institutionFixture){now=now.plusMinutes(1);var value=new BigDecimal("2000.02");var command=new JournalCommand(UUID.randomUUID(),"B2-SYNTHETIC-OPENING",DAY,"Synthetic verified B2 opening",null,List.of(new Line(bank,value,BigDecimal.ZERO),new Line(capital,BigDecimal.ZERO,value)));var journal=gl.importOpening(otherMaker,command);gl.approve(otherChecker,journal.id(),"Independent B2 opening reconciliation");gl.post(otherChecker,journal.id(),true);UUID certificateB2=closing.certify(otherMaker,bank,DAY,"OPENING",value,"Synthetic verified B2 bank source");closing.reviewCertificate(otherChecker,certificateB2,"Independent B2 source review");otherClose=closing.proposeClose(otherMaker,period,"Synthetic B2 opening-only close",false);closing.approveClose(otherChecker,otherClose,"Independent B2 close review");}closing.completeInstitutionClose(checker,period,"Synthetic all-branch acceptance");
  version=statements.save(maker,null,definition(),"Synthetic statement mapping");statements.approve(checker,version,"Independent mapping review");result=statements.finalize(maker,version,close,null);output=outputs.capture(maker,result,new Layout(1,"en",false,false));outputs.review(checker,output,"Independent synthetic output review");var issuerCutoff=statements.verifiedResult(maker,result).recordedCutoff();first=sample("en",DAY,DAY,issuerCutoff);second=sample("sw",DAY,DAY,issuerCutoff);
