 private UUID post(String ref,String amount,boolean opening){BigDecimal value=new BigDecimal(amount);var cmd=new JournalCommand(UUID.randomUUID(),ref,opening?DAY:DAY.plusDays(1),"Synthetic verified source",null,List.of(new Line(bank,value,BigDecimal.ZERO),new Line(capital,BigDecimal.ZERO,value)));var journal=opening?gl.importOpening(maker,cmd):gl.draftManual(maker,cmd);gl.approve(checker,journal.id(),"Independent synthetic source review");return gl.post(checker,journal.id(),opening).id();}
 private StatementDefinition definition(){return new StatementDefinition(1,1,StatementDefinition.Kind.BALANCE_SHEET,"Synthetic financial position","Hali ya fedha ya majaribio",List.of(new StatementDefinition.Row("BANK","Bank","Benki",StatementDefinition.RowKind.ACCOUNT_GROUP,StatementDefinition.Section.ASSETS,StatementDefinition.Unit.TZS,List.of(bank),StatementDefinition.Sign.DEBIT_POSITIVE,null,null,null,true,false,false,null),new StatementDefinition.Row("CAPITAL","Capital","Mtaji",StatementDefinition.RowKind.ACCOUNT_GROUP,StatementDefinition.Section.EQUITY,StatementDefinition.Unit.TZS,List.of(capital),StatementDefinition.Sign.CREDIT_POSITIVE,null,null,null,true,false,false,null)),List.of(),false);}
 private UUID sample(String language){return sample(language,DAY,DAY);}
 private UUID sample(String language,LocalDate from,LocalDate through){return sample(language,from,through,now);}
 private UUID sample(String language,LocalDate from,LocalDate through,OffsetDateTime cutoff){var definition=OperationalReportDefinition.standard(OperationalReportDefinition.Dataset.DISBURSEMENTS,language);if(language.equals("sw")){var columns=new ArrayList<>(definition.columns());Collections.reverse(columns);definition=new OperationalReportDefinition(1,definition.dataset(),definition.title(),definition.footer(),language,true,columns,definition.filters(),definition.sorts(),definition.groups(),definition.totals(),false);}UUID template=templates.save(definition,null,true,maker);templates.publish(template,checker);UUID id=runs.request(maker,new Request(UUID.randomUUID(),template,from,through,cutoff,Set.of(OperationalReportExportService.Format.PDF),null,null));generator.generate(worker.claim().orElseThrow());runs.approve(id,"Independent synthetic layout acceptance",checker);return id;}
 private AppUserPrincipal operator(String branch){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO members(id,sacco_id,station_id,member_no,staff_no,full_name,status,position,created_at,is_member,staff_access_status,password_hash) VALUES(?,?,?,?,?,'Synthetic H officer','ACTIVE','MANAGER',now(),false,'ACTIVE','test-only')",id,institution,branch,id.toString(),id.toString());var member=Member.builder().id(id).saccoId(institution).stationId(branch).memberNo(id.toString()).staffNo(id.toString()).fullName("Synthetic H officer").position(Position.MANAGER).status(MemberStatus.ACTIVE).staffAccessStatus(StaffAccessStatus.ACTIVE).build();when(directory.find(id)).thenReturn(Optional.of(member));return new AppUserPrincipal(member,EnumSet.allOf(UserClaim.class),true);}
 private Proposal proposal(){return new Proposal(UUID.randomUUID(),output,first,second,"Synthetic release proposal only");}
 private UUID approvedRelease(){UUID id=releases.propose(maker,proposal());releases.decide(accountant,id,Stage.ACCOUNTANT,true,"Synthetic accountant acceptance");releases.decide(compliance,id,Stage.COMPLIANCE,true,"Synthetic compliance acceptance");releases.decide(staff,id,Stage.STAFF,true,"Synthetic staff acceptance");return id;}

 private void institutionOutput(){result=statements.finalizeInstitution(maker,version,period,null,null);output=outputs.capture(maker,result,new Layout(1,"en",true,false));outputs.review(checker,output,"Independent synthetic institution output acceptance");}
 @Test @Tag("institution-source") void institutionReleasePinsAllDistinctBranchCutoffsAndUnlocksOnlyCoveredBranches(){
  institutionOutput();var frozen=statements.verifiedResult(maker,result);assertThat(frozen.currentBranchSources()).hasSize(2);assertThat(frozen.currentBranchSources().get(0).recordedCutoff()).isBefore(frozen.currentBranchSources().get(1).recordedCutoff());UUID id=approvedRelease();
  assertThat(jdbc.queryForObject("SELECT count(*) FROM accounting_release_branch_sources WHERE release_id=? AND role='CURRENT'",Integer.class,id)).isEqualTo(2);String receipt=releases.get(maker,id).dependencyJson();assertThat(receipt).contains("INSTITUTION","B1","B2");var retained=tools.jackson.databind.json.JsonMapper.builder().findAndAddModules().build().readTree(receipt).get("currentSource").get("branches");var cutoffs=new ArrayList<java.time.Instant>();for(var branch:retained)cutoffs.add(OffsetDateTime.parse(branch.get("recordedCutoff").asText()).toInstant());assertThat(cutoffs).containsExactlyElementsOf(frozen.currentBranchSources().stream().map(branch->branch.recordedCutoff().toInstant()).toList());
  tx.executeWithoutResult(s->gate.requireLiveRelease(maker,policy,1));tx.executeWithoutResult(s->gate.requireLiveRelease(otherMaker,policy,1));
  jdbc.update("INSERT INTO sacco_stations(id,sacco_id,station_id,active,created_at,updated_at,access_status) VALUES(?,?,'B3',true,now(),now(),'ACTIVE')",UUID.randomUUID(),institution);var uncovered=operator("B3");assertThatThrownBy(()->tx.executeWithoutResult(s->gate.requireLiveRelease(uncovered,policy,1))).hasMessage("accounting.release.error.restricted");
  assertThatThrownBy(()->releases.get(otherMaker,id)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);
 }
