  institutionOutput();UUID id=approvedRelease();var artifact=outputs.artifacts(maker,output).getFirst();var retained=EnumSet.allOf(UserClaim.class);retained.remove(UserClaim.FINANCIAL_REPORTS_INSTITUTION);when(claims.effectiveClaims(any(),anyCollection(),anyBoolean())).thenReturn(retained);
