 @Test void releaseWithdrawalWaitsForAlreadyAuthorizedActualJournalPosting()throws Exception{
  UUID accepted=approvedRelease();gl.createPeriod(maker,DAY.plusDays(1),END);var value=new BigDecimal("0.01");var cmd=new JournalCommand(UUID.randomUUID(),"WITHDRAW-RACE",DAY.plusDays(1),"Synthetic verified source",null,List.of(new Line(bank,value,BigDecimal.ZERO),new Line(capital,BigDecimal.ZERO,value)));var journal=gl.draftManual(maker,cmd);gl.approve(checker,journal.id(),"Independent source review");
  var posted=new CountDownLatch(1);var finish=new CountDownLatch(1);
  doAnswer(call->{posted.countDown();if(!finish.await(10,TimeUnit.SECONDS))throw new AssertionError("Posting latch timeout");return null;}).when(audit).logEvent(eq("ACCOUNTING"),eq(journal.id()),eq("JOURNAL_POSTED"),any(),any(),anyString(),anyString(),anyString(),anyString(),anyString(),any());
  try(var pool=Executors.newFixedThreadPool(2)){
   var posting=pool.submit(()->gl.post(checker,journal.id(),false));assertThat(posted.await(10,TimeUnit.SECONDS)).isTrue();var withdrawal=pool.submit(()->releases.withdraw(accountant,accepted,"Synthetic controlled withdrawal"));
   assertThatThrownBy(()->withdrawal.get(300,TimeUnit.MILLISECONDS)).isInstanceOf(TimeoutException.class);finish.countDown();assertThat(posting.get(10,TimeUnit.SECONDS).state()).isEqualTo("POSTED");withdrawal.get(10,TimeUnit.SECONDS);
   assertThat(releases.get(maker,accepted).getState()).isEqualTo("INVALIDATED");assertThat(gl.post(checker,journal.id(),false).id()).isEqualTo(journal.id());
  }finally{finish.countDown();}
 }
